//! Small AST layer around `syn` used by the macros in this crate.

use std::collections::BTreeSet;

use proc_macro2::TokenStream;
use quote::ToTokens;
use syn::visit::{self, Visit};
use syn::visit_mut::{self, VisitMut};
use syn::{File, Ident, ItemFn, LitStr};

/// A parsed syntax tree together with helpers to inspect and rewrite it.
pub struct Ast {
    item: ItemFn,
}

impl Ast {
    /// Parse a function from the token stream produced by the compiler.
    pub fn parse(tokens: TokenStream) -> syn::Result<Self> {
        Ok(Self { item: syn::parse2::<ItemFn>(tokens)? })
    }

    /// Parse a full Rust source file into a syntax tree.
    pub fn parse_source(source: &str) -> syn::Result<File> {
        syn::parse_file(source)
    }

    pub fn function_name(&self) -> &Ident {
        &self.item.sig.ident
    }

    /// Every identifier referenced anywhere in the function, deduplicated.
    pub fn identifiers(&self) -> BTreeSet<String> {
        let mut collector = IdentCollector::default();
        collector.visit_item_fn(&self.item);
        collector.found
    }

    /// Rename every identifier `from` to `to` in the function.
    pub fn rename(&mut self, from: &str, to: &str) -> syn::Result<usize> {
        let from = validate_ident(from)?;
        let to = parse_ident(to)?;
        let mut renamer = RenameIdent { from, to, count: 0 };
        renamer.visit_item_fn_mut(&mut self.item);
        Ok(renamer.count)
    }

    pub fn into_token_stream(self) -> TokenStream {
        self.item.into_token_stream()
    }
}
```

